import math


def _number(value, name):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise TypeError(f"{name} must be numeric")
    if not math.isfinite(value):
        raise ValueError(f"{name} must be finite")
    return value


def make_scalers(factors):
    try:
        saved = list(factors)
    except TypeError:
        raise TypeError("factors must be iterable") from None
    saved = [_number(factor, "factor") for factor in saved]
    functions = []
    for factor in saved:
        def scale(value):
            return _number(value, "value") * factor
        functions.append(scale)
    return functions
```

